MultiLanguageSpellData['ru'][233429] = {name = "Ледяные удары", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Усиление ледяной водой позволяет дополнительно наносить 1608 ед. урона от магии льда находящимся рядом противникам при каждой атаке в ближнем бою.\n\n Каждая атака в ближнем бою также вызывает срабатывание способности \" Ледяной обвал \", снимая эффект \" Ледяные удары \".\n\n Израсходовав все эффекты, Харджатан использует способность \" Ледяной выброс \"."}
MultiLanguageSpellData['ru'][233430] = {name = "Нестерпимые мучения", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Инквизиция сломила вас. Наносимый вами урон уменьшен на 20%, вероятность попадания снижена на 90%, эффективность исцеления уменьшена на 25%, а получаемый урон увеличен на 90%."}
