MultiLanguageSpellData['ru'][247619] = {name = "Эликсир крови Света", additional_info = "Применение: 2 сек\nИнгредиенты:\nАстральный вьюнок (25), Изначальный саргерит , Хрустальная колба\n[q]Приготовить эликсир крови Света.\nЗадание:\n\"Ограниченные резервы\"\nЗона:\nКрокуун\n\n[q2]Использование: Усиливает игрока энергией Света, позволяя периодически наносить демонам дополнительный урон. Время действия – 30 мин.\n\n Действует только на Расколотых островах и Аргусе вне помещений. (3 Сек Восстановление)"}
