MultiLanguageSpellData['ru'][254410] = {name = "Wind Shear", additional_info = "Радиус действия: 30 м\n{Мгновенное действие} {Восстановление: 12 сек}\n[q]Disrupts the target's concentration with a burst of wind, interrupting spellcasting and preventing any spell in that school from being cast for 3 сек."}
MultiLanguageSpellData['ru'][254411] = {name = "Purge", additional_info = "{4% от базовой мана} {Радиус действия: 30 м}\nМгновенное действие\n[q]Purges the enemy target, removing 1 beneficial Magic effect.[Successfully purging a target grants a stack of Maelstrom Weapon.]"}
MultiLanguageSpellData['ru'][254412] = {name = "Hex", additional_info = "Радиус действия: 30 м\n{Применение: 1.7 сек} {Восстановление: 35 сек}\n[q]Transforms the enemy into a frog for 1 мин. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts."}
MultiLanguageSpellData['ru'][254413] = {name = "Healing Tide Totem", additional_info = "1.12% от базовой мана\n{Мгновенное действие} {Восстановление: 3 мин}\n[q]Summons a totem at your feet for 10 сек, which pulses every 2 sec, healing all party or raid members within 40 yards for ([350% of Spell Power])."}
MultiLanguageSpellData['ru'][254414] = {name = "Ghost Wolf", additional_info = "Мгновенное действие\n[q]Turn into a Ghost Wolf, increasing movement speed by 30% and preventing movement speed from being reduced below 100%."}
MultiLanguageSpellData['ru'][254415] = {name = "Earthbind Totem", additional_info = "Радиус действия: 35 м\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Summons an Earth Totem with (2 * Всего очков здоровья / 100) health at the target location for 20 сек that slows the movement speed of enemies within 10 yards."}
MultiLanguageSpellData['ru'][254416] = {name = "Grounding Totem", additional_info = "1.18% от базовой мана\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Summons an Air Totem with 5 health at the feet of the caster that will redirect all harmful spells cast on a nearby party or raid member to itself. Will not redirect area of effect spells. Lasts 3 сек."}
MultiLanguageSpellData['ru'][254417] = {name = "Earth Shield", additional_info = "{3% от базовой мана} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Protects the target with an earthen shield, reducing all damage the target receives by 15% and causes the target to be healed for ([112.5% of Spell Power]) when they take an attack equal to 4% of their total health. 4 Charges.\n\n Earth Shield can only be placed on one target at a time.\n(Восстановление: 1с)"}
MultiLanguageSpellData['ru'][254418] = {name = "Healing Surge", additional_info = "{4% от базовой мана} {Радиус действия: 40 м}\nПрименение: 1.5 сек\n[q]A quick surge of healing energy that restores 10 of a friendly target's health."}
MultiLanguageSpellData['ru'][254419] = {name = "Riptide", additional_info = "{1.6% от базовой мана} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Restorative waters wash over a friendly target, healing them for 5 and an additional 10 over 15 сек."}
MultiLanguageSpellData['ru'][254420] = {name = "Purify Spirit", additional_info = "{2.6% от базовой мана} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 8 сек}\n[q]Removes all Curse and Magic effects from a friendly target."}
MultiLanguageSpellData['ru'][254421] = {name = "Healing Wave", additional_info = "{1.8% от базовой мана} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]An efficient wave of healing energy that restores 20 of a friendly target’s health."}
MultiLanguageSpellData['ru'][254422] = {name = "Healing Stream Totem", additional_info = "2.2% от базовой мана\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Summons a totem at your feet for 15 сек that heals [ Стремительные потоки : two injured party or raid members / an injured party or raid member] within 40 yards for ([67.68% of Spell Power]) every 2 sec."}
MultiLanguageSpellData['ru'][254423] = {name = "Chain Heal", additional_info = "{5% от базовой мана} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Heals the friendly target for 5, then jumps to heal the most injured nearby party or raid members. Healing is reduced by 30 % after each jump. Heals 4 total targets."}
MultiLanguageSpellData['ru'][254424] = {name = "Lava Burst", additional_info = "{1.2% от базовой мана} {Радиус действия: 40 м}\n{Применение: 2 сек} {Восстановление: 8 сек}\n[q]Hurls molten lava at the target, dealing 2 Fire damage.\n\nСтихии, Совершенствование\nGenerates 12 Maelstrom."}
MultiLanguageSpellData['ru'][254425] = {name = "Earth Shield", additional_info = "Радиус действия: 300 м\nМгновенное действие\n[q]Защищает цель земляным щитом, который уменьшает получаемый ею урон на 10% и восполняет ей ([112.5% of Spell Power]) ед. здоровья, если цель получает урон, равный или превышающий 4% ее максимального запаса здоровья. Максимум зарядов – 4.\n\n Единовременно \"Щит земли\" может действовать только на одну цель."}
