MultiLanguageSpellData['ru'][257702] = {name = "Теневые клинки", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Используя заклинания, наносящие урон, вы можете призвать 6 теневых клинка:теневых клинков. Через 2 сек. клинки устремляются вперед. Каждый клинок наносит 366 ед. урона от темной магии первому противнику на своем пути и увеличивает получаемый им урон от следующих \"Теневых клинков\" на 10% на 3 сек. (вплоть до 50%)."}
