MultiLanguageSpellData['ru'][257715] = {name = "Ритуальная пила", additional_info = "Применение: 2 сек\n[q]В своих ритуалах друсты часто использовали различных животных – точнее, их органы. Чтобы вскрыть грудную клетку и добраться до сердца крупного животного, требовались костяные пилы."}
MultiLanguageSpellData['ru'][257716] = {name = "Древний фолиант с рунами", additional_info = "Применение: 2 сек\n[q]Самые сильные колдуны друстов являлись хранителями фолиантов с магическими формулами, которые служили проводниками их силы. Некоторые ученые пытались расшифровать древний язык формул, но чем больше они понимали, тем глубже погружались в безумие."}
MultiLanguageSpellData['ru'][257717] = {name = "Серп для вскрытия", additional_info = "Применение: 2 сек\n[q]Как оказалось, в своих ритуалах друсты применяли множество инструментов. В частности, серпами они выпускали жертвам внутренности, а затем использовали различные органы для подношений."}
MultiLanguageSpellData['ru'][257718] = {name = "Зазубренный клинок друстов", additional_info = "Применение: 2 сек\n[q]Клинки друстов – внушающие ужас артефакты, которые они применяли как в бою, так и при проведении ритуалов. В руках друста такой клинок точен и смертоносен: он способен пронзить любой жизненно важный орган в мгновение ока."}
MultiLanguageSpellData['ru'][257719] = {name = "Ритуальный фетиш", additional_info = "Применение: 2 сек\n[q]Когда друсты только учились создавать големов, для их оболочки они часто брали кости своих соотечественников. Говорят, что по завершении ритуала от подобных фетишей часто исходил призрачный голубоватый свет – считалось, что так души усопших дают о себе знать."}
MultiLanguageSpellData['ru'][257720] = {name = "Акун'джарская ваза", additional_info = "Применение: 2 сек\n[q]Зандалары поклоняются могущественным духам, которых называют лоа. Рокочущий ящер Акунда – лоа гроз и новых начинаний. Он утверждает, что грозовой ливень смывает с души боль и сожаления, готовя ее к новым испытаниям."}
MultiLanguageSpellData['ru'][257721] = {name = "Урна для усопших", additional_info = "Применение: 2 сек\n[q]Во время последней эпохи Совета племен Зандалар захлестнула кровавая чума, которая унесла жизни тысяч троллей. Было решено, что тела погибших будут сжигаться и храниться в особых урнах, чтобы не загрязнять почву. Со временем этот способ захоронения стал широко использоваться среди зандаларов."}
MultiLanguageSpellData['ru'][257722] = {name = "Идол Резана", additional_info = "Применение: 2 сек\n[q]За минувшие века империей Зандалари правило множество королей. Но каждый из них знал свое место, когда дело касалось великих лоа. Своим лоа короли всегда выбирали сильнейшего, Резана. Резан ценит поступки выше слов, однако серьезно относится к проявлениям непочтительности и злопамятен."}
MultiLanguageSpellData['ru'][257723] = {name = "Капюшон старшего аптекаря", additional_info = "Применение: 2 сек\n[q]У зандаларских алхимиков было свое сплоченное сообщество под названием \"Шадра'Зан\". Те, кто хотел вступить в их гильдию, должны были пройти ритуал, который заключался в поглощении зелья, изготовленного из их собственной крови. Если соискатель выживал, его считали достойным изучения секретов алхимии."}
MultiLanguageSpellData['ru'][257724] = {name = "Маска вуду Бвонсамди", additional_info = "Применение: 2 сек\n[q]Зандалары надевают эти маски во время ритуалов, чтобы почтить лоа смерти и помолиться ему. В свою очередь, Бвонсамди либо отвечает молящимся благосклонностью, либо насылает на них ужасную боль – все зависит от того, в каком настроении он находится. Бвонсамди – покровитель мертвых. Духов своих последователей он сопровождает в свое царство, на так называемую Ту Сторону."}
MultiLanguageSpellData['ru'][257730] = {name = "Благословение зова небес", additional_info = "Применение: 30 сек\n[q]Усиливает находящегося рядом сетрака яростью шторма."}
