MultiLanguageSpellData['ru'][273810] = {name = "Пробуждение Залзеикса", additional_info = "Применение: 2 сек\n[q]Митракс направляет энергию в Залзеикса, тем самым пробуждая свое живое оружие. Накапливаемая энергия создает 2 сферы:сфер забвения.\n\n По завершении поддержания заклинания Залзеикс взрывается, нанося всем игрокам 4701 ед. урона от темной магии и применяя к ним эффект \"Аннигиляция\"."}
MultiLanguageSpellData['ru'][273811] = {name = "Пробуждение Залзеикса", additional_info = "Мгновенное действие\n[q]Митракс направляет энергию в Залзеикса, тем самым пробуждая свое живое оружие. Накапливаемая энергия создает 2 сферы:сфер забвения.\n\n По завершении поддержания заклинания Залзеикс взрывается, нанося всем игрокам 4701 ед. урона от темной магии и применяя к ним эффект \"Аннигиляция\"."}
MultiLanguageSpellData['ru'][273812] = {name = "Духовая трубка поборников Сетралисс", additional_info = "Применение: 2 сек\n[q]Пустынные тролли, которые поклонялись Сетралисс, использовали эти духовые трубки, чтобы охотиться на животных или других троллей. Яд, которым смазаны дротики, мгновенно парализовывал жертву, а уже через минуту она была мертва. Если верить древнему стихотворению, \"Шипом Сетралисс\" пугали непослушных детей: \"Почитай наши святыни, не капризничай, уймись! А иначе из пустыни принесет шип Сетралисс\"."}
