MultiLanguageSpellData['ru'][278508] = {name = "Пальцы хирурга", additional_info = "Мгновенное действие\n[q]Док Муртенс – мастер своего дела. Он может поразить цель оружием в любой руке, а заодно и заразить ее какой-нибудь странной болезнью, с которой ему пришлось столкнуться во врачебной практике.\n(Восстановление: 5с)"}
